L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "\227\129\169\227\129\134\227\130\132\227\130\137\228\184\150\231\149\140\227\129\175\233\129\149\227\129\163\227\129\166\227\130\130\228\186\186\233\150\147\227\129\174\230\156\172\232\179\170\227\129\175\229\164\137\227\130\143\227\130\137\227\129\170\227\129\132\227\130\136\227\129\134\227\129\160\227\128\130"
L14_1.m_Talk_ENG = "Perhaps, even if the world is different, the essence of a person is not."
L14_1.m_Talk_TWN = "\231\156\139\228\190\134\239\188\140\229\141\179\228\189\191\228\184\150\231\149\140\231\153\188\231\148\159\228\186\134\232\174\138\229\140\150\239\188\140\228\186\186\231\154\132\230\156\172\232\179\170\228\185\159\228\184\141\230\156\131\230\148\185\232\174\138\227\128\130"
L14_1.m_Talk_THA = "\224\185\129\224\184\161\224\185\137\224\184\167\224\184\167\224\185\136\224\184\178\224\185\130\224\184\165\224\184\129\224\184\153\224\184\177\224\185\137\224\184\153\224\185\129\224\184\149\224\184\129\224\184\149\224\185\136\224\184\178\224\184\135\224\184\129\224\184\177\224\184\153 \224\185\129\224\184\149\224\185\136\224\184\152\224\184\178\224\184\149\224\184\184\224\185\129\224\184\151\224\185\137\224\184\161\224\184\153\224\184\184\224\184\169\224\184\162\224\185\140\224\184\153\224\184\177\224\185\137\224\184\153\224\185\132\224\184\161\224\185\136\224\185\128\224\184\132\224\184\162\224\185\128\224\184\155\224\184\165\224\184\181\224\185\136\224\184\162\224\184\153\224\185\129\224\184\155\224\184\165\224\184\135~"
L14_1.m_Talk_VTN = "C\195\179 l\225\186\189, cho d\195\185 th\225\186\191 gi\225\187\155i c\195\179 kh\195\161c, nh\198\176ng b\225\186\163n ch\225\186\165t c\225\187\167a m\225\187\153t ng\198\176\225\187\157i th\195\172 kh\195\180ng."
L14_1.m_Talk_SCN = "\231\156\139\230\157\165\239\188\140\229\141\179\228\189\191\228\184\150\231\149\140\229\143\145\231\148\159\228\186\134\229\143\152\229\140\150\239\188\140\228\186\186\231\154\132\230\156\172\232\180\168\228\185\159\228\184\141\228\188\154\230\148\185\229\143\152\227\128\130"
L14_1.m_Talk_DEU = "Es scheint, dass sich das Wesen eines Menschen nicht ver\195\164ndert, selbst wenn sich die Welt um ihn herum ver\195\164ndert."
L14_1.m_Talk_FRA = "On dirait que m\195\170me dans un monde diff\195\169rent, l'essence d'une personne reste identique."
