L20_1.m_Talk_SCN = "\229\133\182\228\187\150\232\162\171\231\180\167\230\128\165\229\134\187\231\187\147\231\154\132\229\174\158\233\170\140\228\189\147\233\131\189\230\173\187\228\186\134\229\144\151\239\188\159"
